/// The symbol covering `addr` and the offset into it, e.g. `wBattleMon+16`.
pub fn ram_name(addr: u16) -> String {
    let i = RAM_SYMBOLS.partition_point(|&(a, _)| a <= addr);
    if i == 0 { return format!("{addr:#06x}"); }
    let (base, name) = RAM_SYMBOLS[i - 1];
    if base == addr { name.to_string() } else { format!("{name}+{}", addr - base) }
}

